var TEN=['1M','3M','6M','1Y','2Y','3Y','5Y','7Y','10Y','20Y','30Y'];
var NOW=[4.382,4.318,4.176,3.944,3.712,3.648,3.694,3.826,3.958,4.318,4.254];
var PRV=[4.379,4.322,4.191,3.972,3.755,3.699,3.752,3.888,4.021,4.375,4.310];
var X0=9,X1=268,Y0=12,Y1=74,LO=3.55,HI=4.45,N=TEN.length;
function px(i){return X0+(X1-X0)*i/(N-1);}
function py(v){return Y1-(v-LO)/(HI-LO)*(Y1-Y0);}
function d(A){var s='';for(var i=0;i<N;i++){s+=(i?'L':'M')+px(i).toFixed(1)+' '+py(A[i]).toFixed(1)+' ';}return s;}
var p=[];
[3.6,3.8,4.0,4.2,4.4].forEach(function(g){var y=py(g);
  p.push('<line class="mcd-curve-overlay-g" x1="9" x2="268" y1="'+y.toFixed(1)+'" y2="'+y.toFixed(1)+'"></line>');
  p.push('<text class="mcd-curve-overlay-yl" x="273" y="'+(y+2.2).toFixed(1)+'">'+g.toFixed(2)+'</text>');});
p.push('<path class="mcd-curve-overlay-pr" d="'+d(PRV)+'"></path>');
p.push('<path class="mcd-curve-overlay-td" d="'+d(NOW)+'"></path>');
for(var i=0;i<N;i++){
  p.push('<circle class="mcd-curve-overlay-dot" cx="'+px(i).toFixed(1)+'" cy="'+py(NOW[i]).toFixed(1)+'" r="1.5"></circle>');
  p.push('<text class="mcd-curve-overlay-xl" x="'+px(i).toFixed(1)+'" y="90">'+TEN[i]+'</text>');}
p.push('<line class="mcd-curve-overlay-cross" x1="0" x2="0" y1="8" y2="78"></line>');
p.push('<circle class="mcd-curve-overlay-cur" cx="0" cy="0" r="2.4"></circle>');
var plot=root.querySelector('.mcd-curve-overlay-plot');
plot.innerHTML='<svg viewBox="0 0 300 94" aria-hidden="true">'+p.join('')+'</svg>';
var cross=root.querySelector('.mcd-curve-overlay-cross'),cur=root.querySelector('.mcd-curve-overlay-cur');
var elT=root.querySelector('.mcd-curve-overlay-ten'),elN=root.querySelector('.mcd-curve-overlay-now'),elP=root.querySelector('.mcd-curve-overlay-prv'),elC=root.querySelector('.mcd-curve-overlay-chg');
function bp(v){return (v>=0?'+':'−')+Math.abs(v).toFixed(1);}
function cls(v){return v>0.05?'mcd-curve-overlay-up':(v<-0.05?'mcd-curve-overlay-dn':'mcd-curve-overlay-fl');}
var k=8;
function setI(i){k=i;
  cross.style.transform='translateX('+px(i).toFixed(1)+'px)';
  cur.setAttribute('cx',px(i).toFixed(1));cur.setAttribute('cy',py(NOW[i]).toFixed(1));
  var c=(NOW[i]-PRV[i])*100;
  elT.textContent=TEN[i];elN.textContent=NOW[i].toFixed(3);elP.textContent=PRV[i].toFixed(3);
  elC.textContent=bp(c)+'bp';elC.className='mcd-curve-overlay-chg '+cls(c);
  plot.setAttribute('aria-label','Tenor '+TEN[i]+', '+NOW[i].toFixed(3)+' percent, '+bp(c)+' basis points');}
function slope(el,a,b){var s=(NOW[b]-NOW[a])*100,q=(PRV[b]-PRV[a])*100,e=root.querySelector(el);
  e.textContent=bp(s)+' ('+bp(s-q)+')';e.className=el.slice(1)+' '+cls(s-q);}
plot.addEventListener('pointermove',function(e){
  var r=plot.getBoundingClientRect(),vx=(e.clientX-r.left)/r.width*300;
  var i=Math.round((vx-X0)/(X1-X0)*(N-1));
  setI(Math.max(0,Math.min(N-1,i)));});
plot.addEventListener('keydown',function(e){
  var s=e.key==='ArrowRight'?1:(e.key==='ArrowLeft'?-1:0);
  if(!s)return;e.preventDefault();setI(Math.max(0,Math.min(N-1,k+s)));});
slope('.mcd-curve-overlay-f1',4,8);slope('.mcd-curve-overlay-f2',6,10);slope('.mcd-curve-overlay-f3',1,8);
setI(8);

