var CCY=['USD','EUR','JPY','GBP','CHF','AUD'];
var PER={USD:1,EUR:0.9198,JPY:152.34,GBP:0.7742,CHF:0.8814,AUD:1.5106};
var CHG={USD:0,EUR:0.24,JPY:-0.38,GBP:0.11,CHF:0.31,AUD:-0.19};
function fmt(v){var s=v>=100?v.toFixed(2):(v>=1?v.toFixed(4):(v>=0.01?v.toFixed(4):v.toFixed(6)));
 return s.charAt(0)==='0'?s.slice(1):s;}
function sg(v){return (v>0?'+':(v<0?'−':''))+Math.abs(v).toFixed(2)+'%';}
function ar(v){return v>0.005?'▲':(v<-0.005?'▼':'–');}
var g=root.querySelector('.mcd-fx-matrix-grid'),h='<span class="mcd-fx-matrix-ch"></span>';
CCY.forEach(function(c){h+='<span class="mcd-fx-matrix-ch">'+c+'</span>';});
CCY.forEach(function(r,ri){
  h+='<span class="mcd-fx-matrix-rh" role="rowheader">'+r+'</span>';
  CCY.forEach(function(c,ci){
    if(r===c){h+='<span class="mcd-fx-matrix-d">'+r+'</span>';return;}
    var v=PER[c]/PER[r],p=CHG[r]-CHG[c];
    var k=p>0.005?'mcd-fx-matrix-up':(p<-0.005?'mcd-fx-matrix-dn':'mcd-fx-matrix-fl');
    h+='<span class="mcd-fx-matrix-c '+k+'" data-r="'+ri+'" data-c="'+ci+'" data-p="'+r+c+'" data-v="'+fmt(v)+'" data-x="'+p.toFixed(2)+'" aria-label="'+r+c+' '+fmt(v)+', '+sg(p)+' on the day"><b>'+fmt(v)+'</b><i>'+ar(p)+sg(p)+'</i></span>';});});
g.innerHTML=h;
var cells=root.querySelectorAll('.mcd-fx-matrix-c');
var fp=root.querySelector('.mcd-fx-matrix-pair'),fr=root.querySelector('.mcd-fx-matrix-rate'),fx=root.querySelector('.mcd-fx-matrix-pct');
function show(el,pin){
  var r=el.getAttribute('data-r'),c=el.getAttribute('data-c'),p=parseFloat(el.getAttribute('data-x'));
  for(var i=0;i<cells.length;i++){var q=cells[i];
    q.classList.toggle('mcd-fx-matrix-hi',q.getAttribute('data-r')===r||q.getAttribute('data-c')===c);
    if(pin)q.classList.toggle('mcd-fx-matrix-sel',q===el);}
  fp.textContent=el.getAttribute('data-p');
  fr.textContent=el.getAttribute('data-v');
  fx.textContent=ar(p)+' '+sg(p);
  fx.className='mcd-fx-matrix-pct '+(p>0.005?'mcd-fx-matrix-up':(p<-0.005?'mcd-fx-matrix-dn':'mcd-fx-matrix-fl'));}
g.addEventListener('mouseover',function(e){var t=e.target.closest('.mcd-fx-matrix-c');if(t)show(t,false);});
g.addEventListener('click',function(e){var t=e.target.closest('.mcd-fx-matrix-c');if(t)show(t,true);});
var first=root.querySelector('.mcd-fx-matrix-c[data-p="EURUSD"]');
if(first)show(first,true);

