var D=[
['02:00','DE','Factory Orders m/m',2,2.9,1.5,-1.7,'%'],
['04:00','EZ','GDP q/q (2nd est)',2,0.2,0.2,0.3,'%'],
['05:00','EZ','HICP Core y/y flash',3,2.8,2.9,2.9,'%'],
['08:30','US','Nonfarm Payrolls',3,142,165,89,'k'],
['08:30','US','Unemployment Rate',3,4.2,4.2,4.3,'%'],
['08:30','US','Avg Hourly Earn m/m',2,0.4,0.3,0.2,'%'],
['10:00','US','ISM Services PMI',3,51.5,51.1,51.4,'i'],
['11:30','CA','Ivey PMI SA',1,null,54.0,53.2,'i'],
['14:00','US','Fed Beige Book',2,null,null,null,'x'],
['15:00','US','Consumer Credit',1,null,12.5,8.9,'B']];
function f(v,u){if(v===null||v===undefined)return '—';
 if(u==='k')return (v<0?'−':'')+Math.abs(v).toFixed(0)+'k';
 if(u==='%')return (v<0?'−':'')+Math.abs(v).toFixed(1)+'%';
 if(u==='B')return '$'+v.toFixed(1)+'B';
 if(u==='i')return v.toFixed(1);
 return '—';}
function fd(v,u){var s=(v>=0?'+':'−')+Math.abs(v).toFixed(u==='k'?0:1);
 return s+(u==='k'?'k':(u==='%'?'pp':''));}
var list=root.querySelector('.mcd-econ-calendar-list'),h='',nextIx=-1;
D.forEach(function(r,i){
  var act=r[4],fc=r[5],tag,tc;
  if(act===null){tag='SCHED';tc='mcd-econ-calendar-pend';if(nextIx<0)nextIx=i;}
  else if(fc===null){tag='RELEASED';tc='mcd-econ-calendar-line';}
  else{var dv=act-fc;
    if(Math.abs(dv)<1e-9){tag='IN LINE';tc='mcd-econ-calendar-line';}
    else if(dv>0){tag='▲ BEAT '+fd(dv,r[7]);tc='mcd-econ-calendar-beat';}
    else{tag='▼ MISS '+fd(dv,r[7]);tc='mcd-econ-calendar-miss';}}
  var stars='';for(var s=0;s<3;s++)stars+=s<r[3]?'<b>●</b>':'●';
  h+='<div class="mcd-econ-calendar-row" role="listitem" data-i="'+r[3]+'" data-cy="'+r[1]+'" data-a="'+(act===null?0:1)+'">'
   +'<div class="mcd-econ-calendar-l1"><span class="mcd-econ-calendar-tm">'+r[0]+'</span>'
   +'<span class="mcd-econ-calendar-cy">'+r[1]+'</span>'
   +'<span class="mcd-econ-calendar-ev">'+r[2]+'</span>'
   +'<span class="mcd-econ-calendar-im">'+stars+'</span></div>'
   +'<div class="mcd-econ-calendar-l2"><span>A <b>'+f(act,r[7])+'</b> · F '+f(fc,r[7])+' · <i class="mcd-econ-calendar-pr">P '+f(r[6],r[7])+'</i></span>'
   +'<span class="mcd-econ-calendar-tag '+tc+'">'+tag+'</span></div></div>';});
list.innerHTML=h;
var rows=root.querySelectorAll('.mcd-econ-calendar-row');
if(nextIx>=0){rows[nextIx].classList.add('mcd-econ-calendar-next');
  root.querySelector('.mcd-econ-calendar-nx').textContent='NEXT · '+D[nextIx][0]+' '+D[nextIx][1]+' '+D[nextIx][2];}
var cnt=root.querySelector('.mcd-econ-calendar-cnt');
function apply(f2){var n=0;
  for(var i=0;i<rows.length;i++){var r=rows[i],ok=true;
    if(f2==='high')ok=r.getAttribute('data-i')==='3';
    else if(f2==='us')ok=r.getAttribute('data-cy')==='US';
    else if(f2==='ahead')ok=r.getAttribute('data-a')==='0';
    r.style.display=ok?'':'none';if(ok)n++;}
  cnt.textContent=n+(f2==='all'?'':' / '+rows.length);}
var chips=root.querySelectorAll('.mcd-econ-calendar-chip');
for(var ci=0;ci<chips.length;ci++)chips[ci].addEventListener('click',function(e){
  for(var j=0;j<chips.length;j++){var on=chips[j]===e.currentTarget;
    chips[j].classList.toggle('mcd-econ-calendar-on',on);chips[j].setAttribute('aria-pressed',on?'true':'false');}
  apply(e.currentTarget.getAttribute('data-f'));});
apply('all');
var cd=root.querySelector('.mcd-econ-calendar-cd'),t=4364;
function pad(v){return (v<10?'0':'')+v;}
function tick(){cd.textContent='T− '+pad(Math.floor(t/3600))+':'+pad(Math.floor(t/60)%60)+':'+pad(t%60);}
tick();
var iv=setInterval(function(){
  if(!root.isConnected){clearInterval(iv);return;}
  if(t>0)t--;
  tick();},1000);

