var D=[
['CLV5','WTI CRUDE OCT5',63.42,64.00,62.98,0.01,2,'ENE'],
['COX5','BRENT NOV5',66.95,67.46,66.58,0.01,2,'ENE'],
['NGV5','NAT GAS OCT5',2.874,2.812,3.106,0.001,3,'ENE'],
['GCZ5','GOLD DEC5',3512.4,3493.8,3541.2,0.1,1,'MET'],
['SIZ5','SILVER DEC5',40.62,40.18,40.94,0.01,2,'MET'],
['HGZ5','COPPER DEC5',4.5285,4.5500,4.5810,0.0005,4,'MET'],
['ZCZ5','CORN DEC5',419.25,416.50,432.00,0.25,2,'AGS'],
['ZWZ5','WHEAT DEC5',542.50,545.75,561.25,0.25,2,'AGS']];
var S=D.map(function(r){return {c:r[0],n:r[1],last:r[2],pc:r[3],m2:r[4],tk:r[5],dp:r[6],sec:r[7]};});
function sg(v,n){return (v>=0?'+':'−')+Math.abs(v).toFixed(n);}
function kl(v){return v>0?'mcd-commodity-board-up':(v<0?'mcd-commodity-board-dn':'mcd-commodity-board-fl');}
var box=root.querySelector('.mcd-commodity-board-rows'),h='';
S.forEach(function(r,i){
  var df=r.m2-r.last,back=df<0;
  h+='<div class="mcd-commodity-board-row" data-i="'+i+'">'
   +'<span class="mcd-commodity-board-cd">'+r.c+'</span>'
   +'<span class="mcd-commodity-board-nm">'+r.n+'</span>'
   +'<span class="mcd-commodity-board-lp">—</span>'
   +'<span class="mcd-commodity-board-nt">—</span>'
   +'<span class="mcd-commodity-board-pc">—</span>'
   +'<span class="mcd-commodity-board-cv '+(back?'mcd-commodity-board-back':'mcd-commodity-board-cont')+'">'+(back?'BACK':'CONT')+'</span></div>';});
box.innerHTML=h;
var rows=root.querySelectorAll('.mcd-commodity-board-row');
function paint(i,flash){var r=S[i],el=rows[i];
  var net=r.last-r.pc,pct=net/r.pc*100;
  var lp=el.querySelector('.mcd-commodity-board-lp'),nt=el.querySelector('.mcd-commodity-board-nt'),pc=el.querySelector('.mcd-commodity-board-pc');
  lp.textContent=r.last.toFixed(r.dp);
  nt.textContent=sg(net,r.dp);nt.className='mcd-commodity-board-nt '+kl(net);
  pc.textContent=sg(pct,2)+'%';pc.className='mcd-commodity-board-pc '+kl(net);
  if(flash){lp.classList.remove('mcd-commodity-board-fu','mcd-commodity-board-fd');
    void lp.offsetWidth;lp.classList.add(flash>0?'mcd-commodity-board-fu':'mcd-commodity-board-fd');}}
var sec=root.querySelector('.mcd-commodity-board-sec');
function sectors(){var g={},o=[];
  S.forEach(function(r){if(!g[r.sec]){g[r.sec]=[0,0];o.push(r.sec);}
    g[r.sec][0]+=(r.last-r.pc)/r.pc*100;g[r.sec][1]++;});
  sec.innerHTML=o.map(function(k){var v=g[k][0]/g[k][1];
    return k+' <b class="'+kl(v)+'">'+sg(v,2)+'%</b>';}).join(' · ');}
var det=root.querySelector('.mcd-commodity-board-det');
box.addEventListener('mouseover',function(e){var t=e.target.closest('.mcd-commodity-board-row');
  if(!t)return;var r=S[+t.getAttribute('data-i')],df=r.m2-r.last;
  det.textContent=r.c+' M1 '+r.last.toFixed(r.dp)+' / M2 '+r.m2.toFixed(r.dp)+' · '
    +(df<0?'BACKWARDATION ':'CONTANGO ')+sg(df,r.dp);});
for(var i=0;i<S.length;i++)paint(i,0);
sectors();
var iv=setInterval(function(){
  if(!root.isConnected){clearInterval(iv);return;}
  var i=Math.floor(Math.random()*S.length),r=S[i];
  var steps=Math.floor(Math.random()*5)-2;
  if(!steps)steps=Math.random()<0.5?1:-1;
  r.last=Math.round((r.last+steps*r.tk)/r.tk)*r.tk;
  paint(i,steps>0?1:-1);sectors();},1200);

