var SC=2.5;
var D=[['US',3.958,2.9],['DE',2.284,2.1],['FR',3.062,1.9],['IT',3.622,1.7],['UK',4.028,3.4],
['JP',1.588,3.1],['CA',3.184,2.4],['AU',4.212,2.8],['CH',0.412,0.6],['NZ',4.284,2.7]];
var S=D.map(function(r){return {ccy:r[0],nom:r[1],cpi:r[2],real:r[1]-r[2]};});
function sg(v){return (v>=0?'+':'−')+Math.abs(v).toFixed(2);}
var box=root.querySelector('.mcd-real-yields-rows');
function draw(list){var h='';
  list.forEach(function(r){
    var w=Math.min(50,Math.abs(r.real)/SC*50),left=r.real>=0?50:50-w;
    h+='<div class="mcd-real-yields-row"><span class="mcd-real-yields-cy">'+r.ccy+'</span>'
     +'<span class="mcd-real-yields-nm">'+r.nom.toFixed(3)+'</span>'
     +'<span class="mcd-real-yields-cp">'+r.cpi.toFixed(1)+'</span>'
     +'<span class="mcd-real-yields-rl '+(r.real>=0?'mcd-real-yields-up':'mcd-real-yields-dn')+'">'+sg(r.real)+'</span>'
     +'<span class="mcd-real-yields-tr"><i class="mcd-real-yields-zero"></i>'
     +'<i class="mcd-real-yields-bar '+(r.real>=0?'mcd-real-yields-pos':'mcd-real-yields-neg')+'" style="left:'+left.toFixed(2)+'%;width:'+w.toFixed(2)+'%"></i></span></div>';});
  box.innerHTML=h;}
var md=root.querySelector('.mcd-real-yields-md'),ng=root.querySelector('.mcd-real-yields-ng');
function stats(){var a=S.map(function(r){return r.real;}).sort(function(x,y){return x-y;});
  var n=a.length,m=n%2?a[(n-1)/2]:(a[n/2-1]+a[n/2])/2;
  md.textContent=sg(m)+'%';md.className='mcd-real-yields-md '+(m>=0?'mcd-real-yields-up':'mcd-real-yields-dn');
  var neg=a.filter(function(v){return v<0;}).length;
  ng.textContent=neg+'/'+n+' NEGATIVE REAL';}
var LBL={ccy:'CTY',nom:'NOM',cpi:'CPI',real:'REAL'};
var key='real',btns=root.querySelectorAll('.mcd-real-yields-sb');
function sort(k){key=k;
  var l=S.slice();
  if(k==='ccy')l.sort(function(a,b){return a.ccy<b.ccy?-1:1;});
  else l.sort(function(a,b){return b[k]-a[k];});
  for(var i=0;i<btns.length;i++){var on=btns[i].getAttribute('data-k')===k;
    btns[i].classList.toggle('mcd-real-yields-on',on);
    var t=LBL[btns[i].getAttribute('data-k')];
    btns[i].textContent=on?t+(k==='ccy'?' ▲':' ▼'):t;}
  draw(l);}
for(var i=0;i<btns.length;i++)btns[i].addEventListener('click',function(e){sort(e.currentTarget.getAttribute('data-k'));});
sort('real');stats();
